// Notific8 — decide se o alerta sai, e evita flood.
//
// Duas perguntas:
//   1) o site esta ruim? (codigo de erro OU pagina sem o texto esperado)
//   2) ja avisei isso? (estado guardado entre execucoes)
//
// O estado vive em $getWorkflowStaticData('global'): e um objeto que o n8n
// grava junto do workflow e devolve na execucao seguinte. Sem ele, um site
// caido geraria 12 mensagens por hora.

const REPETIR_APOS_MIN = 60;   // enquanto durar, relembra de hora em hora

const conf = $('Configuracao').first().json;
const r = $input.first().json;
const estado = $getWorkflowStaticData('global');

const codigo = Number(r.statusCode ?? 0);
const corpo = typeof r.body === 'string' ? r.body : JSON.stringify(r.body ?? '');

let problema = null;
if (codigo === 0) problema = 'sem resposta (timeout ou DNS)';
else if (codigo >= 400) problema = 'HTTP ' + codigo;
else if (conf.texto_esperado && !corpo.includes(conf.texto_esperado)) {
  // Armadilha classica: o servidor responde 200 e entrega pagina de erro.
  problema = 'respondeu 200 sem "' + conf.texto_esperado + '" na pagina';
}

const agora = Date.now();
const estavaRuim = Boolean(estado.problema);
const minutosDesdeAviso = (agora - Number(estado.ultimo_aviso ?? 0)) / 60000;

let alertar = false;
let assunto = '';

if (problema && !estavaRuim) {
  alertar = true; assunto = 'CAIU';                    // virada bom -> ruim
} else if (problema && minutosDesdeAviso >= REPETIR_APOS_MIN) {
  alertar = true; assunto = 'AINDA CAIDO';             // lembrete de hora em hora
} else if (!problema && estavaRuim) {
  alertar = true; assunto = 'VOLTOU';                  // virada ruim -> bom
}

if (alertar) estado.ultimo_aviso = agora;
estado.problema = problema;   // null quando esta tudo bem

return [{
  json: {
    alertar,
    assunto,
    problema: problema ?? 'nenhum',
    codigo,
    url: conf.url,
    verificado_em: new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }),
  },
}];
